CREATE TABLE "fragments" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "kind" text NOT NULL,
  "chat_id" bigint,
  "owner" bigint,
  "slug" text NOT NULL,
  "title" text NOT NULL,
  "path" text NOT NULL,
  "scope" text,
  "position" bigint NOT NULL,
  "active" bigint NOT NULL,
  "last_hit_at" bigint,
  "hits" bigint NOT NULL,
  "set_by" bigint,
  "set_at" bigint NOT NULL,
  "hand" bigint,
  "hand_at" bigint,
  "keywords" text NOT NULL DEFAULT '[]',
  "items" text NOT NULL DEFAULT '[]',
  "written_on" text,
  "confirmed_on" text,
  "status" text NOT NULL DEFAULT 'open',
  "body_hash" text,
  "agent" text NOT NULL,
  "all_agents" bigint NOT NULL DEFAULT 0,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE "memories" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "slug" text NOT NULL,
  "type" text NOT NULL,
  "chat_id" bigint,
  "reach" text NOT NULL,
  "condition" text NOT NULL,
  "action" text NOT NULL,
  "for_user" bigint,
  "message_id" bigint,
  "todo_id" bigint,
  "set_by" bigint,
  "set_at" bigint NOT NULL,
  "active" bigint NOT NULL,
  "last_hit_at" bigint,
  "hits" bigint NOT NULL,
  "done_at" bigint,
  "done_text" text,
  "down_reason" text,
  "down_at" bigint,
  "candidate_why" text,
  "candidate_at" bigint,
  "event" text NOT NULL DEFAULT '',
  "event_met_at" bigint,
  "moved_at" bigint,
  "agent" text NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE "notes" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "chat_id" bigint NOT NULL,
  "author" bigint,
  "text" text NOT NULL,
  "created_at" bigint NOT NULL,
  "agent" text NOT NULL,
  "shared" bigint NOT NULL DEFAULT 0,
  "consumed_at" bigint,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE "reminders" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "chat_id" bigint NOT NULL,
  "user_id" bigint,
  "due_at" bigint NOT NULL,
  "reason" text,
  "memory_id" bigint,
  "every" text,
  "fired" bigint NOT NULL DEFAULT 0,
  "created_at" bigint NOT NULL,
  "agent" text NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE TABLE "session_people" (
  "session_id" text NOT NULL,
  "path" text NOT NULL,
  "version" text NOT NULL,
  "loaded_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("session_id", "path")
);

CREATE TABLE "settings" (
  "key" text,
  "value" text NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key")
);

CREATE TABLE "watches" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "chat_id" bigint NOT NULL,
  "by_chat" bigint NOT NULL,
  "kind" text NOT NULL,
  "condition" text,
  "name" text,
  "note" text NOT NULL,
  "dedupe_key" text NOT NULL,
  "interval_seconds" bigint,
  "due_at" bigint,
  "deadline_at" bigint NOT NULL,
  "state" text NOT NULL DEFAULT 'active',
  "unit" text,
  "run_id" bigint,
  "armed_at" bigint,
  "last_checked_at" bigint,
  "last_exit" bigint,
  "instruction_id" bigint,
  "created_at" bigint NOT NULL,
  "ended_at" bigint,
  "memory_id" bigint,
  "agent" text NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "fragments_one" ON "fragments" (kind, agent, COALESCE(chat_id, 0), COALESCE(owner, 0), slug);
CREATE INDEX "fragments_scope" ON "fragments" (kind, chat_id, active);
CREATE INDEX "memories_room" ON "memories" (chat_id, active);
CREATE UNIQUE INDEX "memories_slug" ON "memories" (slug);
CREATE INDEX "memories_standing" ON "memories" (chat_id, active, done_at);
CREATE INDEX "memories_todo" ON "memories" (todo_id);
CREATE UNIQUE INDEX "watches_active_dedupe" ON "watches" (by_chat, dedupe_key) WHERE state = 'active';
CREATE INDEX "watches_state" ON "watches" (state);
